#!/usr/bin/env bash
set -euo pipefail
root=/var/lib/steam-top-bootstrap/first-deploy;config=/etc/steam-top-bootstrap/trust.json;[[ $(id -u) -eq 0 && $# -eq 0 && -L $root/current ]]||exit 1;generation=$(realpath "$root/current");[[ $generation == "$root/generations/"* && -d $generation && ! -L $generation ]];payload=$generation/payload.json;sig=$payload.sig;[[ -f $payload && ! -L $payload && -f $sig && ! -L $sig && $(stat -c '%u %a' "$payload") == '0 400' && $(stat -c '%u %a' "$sig") == '0 400' ]];allowed=$(node -p 'require(process.argv[1]).productionStateAllowedSigners' "$config");signer=$(node -p 'require(process.argv[1]).signerKeyId' "$payload");ssh-keygen -Y verify -q -f "$allowed" -I "$signer" -n steam-top-first-deploy-state -s "$sig" <"$payload";[[ $(basename "$generation") == "$(sha256sum "$payload"|awk '{print $1}')" ]];node -e 'const x=require(process.argv[1]);if(x.schemaVersion!==1||x.purpose!=="steam-top-first-deploy-state"||!["pending","db-claimed","consumed"].includes(x.phase))process.exit(1);console.log([x.phase,x.authorizationNonce,x.hostId,x.bootstrapDigest,x.installReceiptDigest].join(" "))' "$payload"
